void Put32(std::vector<unsigned char>& b,std::uint32_t v){for(int i=0;i<4;++i)b.push_back(static_cast<unsigned char>(v>>(8*i)));}
void Put64(std::vector<unsigned char>& b,std::uint64_t v){for(int i=0;i<8;++i)b.push_back(static_cast<unsigned char>(v>>(8*i)));}
void PutString(std::vector<unsigned char>& b,const std::string& v){Put32(b,static_cast<std::uint32_t>(v.size()));b.insert(b.end(),v.begin(),v.end());}
