void AtomicCopy(const std::wstring& source,const std::wstring& target,const std::wstring& suffix){Directories(Parent(target));if(!NoReparse(source)||!NoReparse(target,true))throw std::runtime_error("Refusing linked update file");const auto temp=target+L".hllcalc-new-"+suffix;if(GetFileAttributesW(temp.c_str())!=INVALID_FILE_ATTRIBUTES)throw std::runtime_error("Temporary update destination already exists");if(!CopyFileW(source.c_str(),temp.c_str(),TRUE))WinError("Cannot stage replacement file");if(!MoveFileExW(temp.c_str(),target.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)){DWORD e=GetLastError();DeleteFileW(temp.c_str());SetLastError(e);WinError("Cannot replace update file");}}
