void AcknowledgeStartup(const std::wstring& exe,const std::string& version){int argc=0;LPWSTR* argv=CommandLineToArgvW(GetCommandLineW(),&argc);if(!argv)return;try{if(argc==3&&wcscmp(argv[1],L"--update-started")==0){auto stage=FullPath(argv[2]);auto r=LoadRequest(stage);if(_wcsicmp(r.prepared.target.c_str(),exe.c_str())||r.prepared.version!=version)throw std::runtime_error("Update startup identity mismatch");auto it=std::find(r.prepared.files.begin(),r.prepared.files.end(),"HLLCalc.exe");if(it==r.prepared.files.end()||HashFile(exe)!=r.hashes[static_cast<size_t>(it-r.prepared.files.begin())])throw std::runtime_error("Update startup hash mismatch");WriteFileBytes(Join(stage,L".started"),std::vector<unsigned char>{'O','K'});}}catch(...){ }LocalFree(argv);}
